package com.github.games647.changeskin.sponge.command;

import com.github.games647.changeskin.sponge.ChangeSkinSponge;
import com.github.games647.changeskin.sponge.PomData;
import com.github.games647.changeskin.sponge.task.SkinSelector;
import com.google.inject.Inject;

import org.spongepowered.api.command.CommandResult;
import org.spongepowered.api.command.exception.CommandException;
import org.spongepowered.api.command.parameter.CommandContext;
import org.spongepowered.api.command.parameter.Parameter;
import org.spongepowered.api.command.parameter.managed.standard.Source;
import org.spongepowered.api.entity.living.player.Player;
import org.spongepowered.api.scheduler.Task;

public class SelectCommand implements ChangeSkinCommand {

    private final ChangeSkinSponge plugin;

    @Inject
    SelectCommand(ChangeSkinSponge plugin) {
        this.plugin = plugin;
    }

    @Override
    public CommandSpec buildSpec() {
        Parameter.Value<String> skinNameParam = Parameter.string().key("skinName").build();
        return CommandSpec.builder()
                .parameters(skinNameParam)
                .permission(PomData.ARTIFACT_ID + ".command.skinselect.base")
                .executor(this::execute)
                .build();
    }

    public CommandResult execute(CommandContext context) throws CommandException {
        Object src = context.requireOne(Source.class, Object.class);
        if (!(src instanceof Player)) {
            plugin.sendMessage((org.spongepowered.api.command.CommandSource) src, "no-console");
            return CommandResult.success();
        }

        String skinName = context.requireOne(Parameter.key("skinName", String.class)).toLowerCase().replace("skin-", "");

        try {
            int targetId = Integer.parseInt(skinName);
            Player receiver = (Player) src;
            Task.builder().async().execute(new SkinSelector(plugin, receiver, targetId)).submit(plugin);
        } catch (NumberFormatException numberFormatException) {
            plugin.sendMessage((org.spongepowered.api.command.CommandSource) src, "invalid-skin-name");
        }

        return CommandResult.success();
    }
}

